<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{Booking,Expense,Payment}; use Illuminate\Support\Facades\DB;
class DashboardController extends Controller { public function __invoke(){ $month=[now()->startOfMonth(),now()->endOfMonth()];$revenue=Booking::whereBetween('function_date',$month)->where('status','!=','Cancelled')->sum('final_amount');$paid=Payment::sum('amount');$expenses=Expense::sum('amount');$series=collect(range(5,0))->map(function($n){$d=now()->subMonths($n);return ['month'=>$d->format('M'),'revenue'=>(float)Booking::whereYear('function_date',$d->year)->whereMonth('function_date',$d->month)->sum('final_amount'),'expenses'=>(float)Expense::whereYear('date',$d->year)->whereMonth('date',$d->month)->sum('amount')];});return ['stats'=>['today'=>Booking::whereDate('function_date',today())->count(),'upcoming'=>Booking::whereDate('function_date','>=',today())->whereNotIn('status',['Completed','Cancelled'])->count(),'month_bookings'=>Booking::whereBetween('function_date',$month)->count(),'revenue'=>(float)$revenue,'received'=>(float)$paid,'outstanding'=>(float)max(0,Booking::sum('final_amount')-$paid),'expenses'=>(float)$expenses,'profit'=>(float)(Booking::sum('final_amount')-$expenses)],'series'=>$series,'statuses'=>Booking::select('status',DB::raw('count(*) total'))->groupBy('status')->get(),'recent_bookings'=>Booking::with('customer')->latest()->limit(5)->get(),'recent_expenses'=>Expense::latest()->limit(5)->get()]; } }
